import json

SCHEMA = {
    "type": "object",
    "required": ["name", "score", "tags"],
    "properties": {
        "name": {"type": "string", "minLength": 1},
        "score": {"type": "integer", "minimum": 0, "maximum": 100},
        "tags": {"type": "array", "maxItems": 3,
                 "items": {"type": "string", "enum": ["a", "b", "c"]}},
        "level": {"type": "string", "enum": ["low", "mid", "high"]},
    },
}

TYPE_MAP = {"object": dict, "array": list, "string": str,
            "integer": int, "number": (int, float), "boolean": bool}


def check(inst, sch, path="$"):
    errs = []

    def err(msg):
        errs.append("%s: %s" % (path, msg))

    st = sch.get("type")
    if st:
        py = TYPE_MAP[st]
        if not isinstance(inst, py) or (st in ("integer", "number") and isinstance(inst, bool)):
            err("类型应为 %s，实际 %s" % (st, type(inst).__name__))
            return errs
    if "enum" in sch and inst not in sch["enum"]:
        err("取值 %r 不在枚举 %s 中" % (inst, sch["enum"]))
    if st == "string":
        if "minLength" in sch and len(inst) < sch["minLength"]:
            err("长度 %d < minLength %d" % (len(inst), sch["minLength"]))
    if st in ("integer", "number"):
        if "minimum" in sch and inst < sch["minimum"]:
            err("值 %s < minimum %s" % (inst, sch["minimum"]))
        if "maximum" in sch and inst > sch["maximum"]:
            err("值 %s > maximum %s" % (inst, sch["maximum"]))
    if st == "array":
        if "maxItems" in sch and len(inst) > sch["maxItems"]:
            err("元素数 %d > maxItems %d" % (len(inst), sch["maxItems"]))
        if "items" in sch:
            for i, v in enumerate(inst):
                errs.extend(check(v, sch["items"], "%s[%d]" % (path, i)))
    if st == "object":
        for r in sch.get("required", []):
            if r not in inst:
                err("缺少必填字段 %s" % r)
        for k, sub in sch.get("properties", {}).items():
            if k in inst:
                errs.extend(check(inst[k], sub, "%s.%s" % (path, k)))
    return errs


CANDIDATES = [
    ("ok-1", '{"name": "问题A", "score": 90, "tags": ["a", "b"], "level": "high"}'),
    ("ok-2", '{"name": "问题B", "score": 0, "tags": []}'),
    ("miss-field", '{"name": "问题C", "tags": ["a"]}'),
    ("bad-range", '{"name": "问题D", "score": 120, "tags": ["a"]}'),
    ("bad-enum", '{"name": "问题E", "score": 50, "tags": ["z"]}'),
    ("too-many", '{"name": "问题F", "score": 50, "tags": ["a", "b", "c", "a"]}'),
    ("not-json", '{"name": "问题G", "score": 50, "tags": ["a"],}'),
]

passed = 0
for name, raw in CANDIDATES:
    try:
        inst = json.loads(raw)
    except json.JSONDecodeError as e:
        print("%-12s JSON 解析失败: %s" % (name, str(e)[:60]))
        continue
    errs = check(inst, SCHEMA)
    if errs:
        print("%-12s 不通过 (%d 处)" % (name, len(errs)))
        for e in errs[:3]:
            print("             %s" % e)
    else:
        passed += 1
        print("%-12s 通过" % name)

print()
print("通过率 = %d/%d = %.2f" % (passed, len(CANDIDATES), passed / len(CANDIDATES)))
